I'll analyze the Fortran routine and translate it to C++17/Eigen. Let me start by understanding the key computation.

The routine computes the stiffness matrix for a 4-node tetrahedral element. The core steps:
1. Build H matrix (4x4) from node coordinates
2. Invert H, get determinant
3. Build G material matrix (6x6)
4. Build C matrices (6x3 each, 4 of them)
5. Compute K = C^T * G * C * (det/6)

Let me write the C++ code.

```cpp
#include <Eigen/Dense>
#include <iostream>
#include <iomanip>
#include <cmath>

using namespace Eigen;

int main() {
    // Node coordinates
    // N1=(0,0,0), N2=(1,0,0), N3=(0,1,0), N4=(0,0,1)
    double x1=0,y1=0,z1=0;
    double x2=1,y2=0,z2=0;
    double x3=0,y3=1,z3=0;
    double x4=0,y4=0,z4=1;

    double E  = 200e9;
    double nu = 0.3;
    double GG = E / (2.0*(1.0+nu));

    // Build H (4x4) - row i = [1, xi, yi, zi]
    Matrix4d H;
    H << 1.0, x1, y1, z1,
         1.0, x2, y2, z2,
         1.0, x3, y3, z3,
         1.0, x4, y4, z4;

    // Invert H and get determinant
    double HDETER = H.determinant();
    Matrix4d Hinv = H.inverse();

    // G material matrix (6x6)
    Matrix<double,6,6> G = Matrix<double,6,6>::Zero();
    double TEMP1 = (1.0+nu)*(1.0-2.0*nu);
    double c1 = E*(1.0-nu)/TEMP1;
    double c2 = E*nu/TEMP1;

    // Fortran G is 1-indexed stored column-major-ish; map indices:
    // G(1)=c1, G(8)=c1, G(15)=c1
    // G(2)=c2, G(3)=c2, G(7)=c2, G(9)=c2, G(13)=c2, G(14)=c2
    // G(22)=GG, G(29)=GG, G(36)=GG
    // Fortran G is 6x6 column-major: index = (col-1)*6 + row
    // G(1) -> row1,col1 ; G(8) -> row2,col2 ; G(15) -> row3,col3
    // G(2) -> row2,col1 ; G(3) -> row3,col1 ; G(7) -> row1,col2
    // G(9) -> row3,col2 ; G(13) -> row1,col3 ; G(14) -> row2,col3
    // G(22) -> row4,col4 ; G(29) -> row5,col5 ; G(36) -> row6,col6
    G(0,0)=c1; G(1,1)=c1; G(2,2)=c1;
    G(1,0)=c2; G(2,0)=c2; G(0,1)=c2; G(2,1)=c2; G(0,2)=c2; G(1,2)=c2;
    G(3,3)=GG; G(4,4)=GG; G(5,5)=GG;

    // Build 4 C matrices (6x3 each). Fortran C is 72 doubles, C(18*I-17) start.
    // C(J+1)=H(I+4), C(J+5)=H(I+8), C(J+9)=H(I+12),
    // C(J+11)=H(I+12), C(J+12)=H(I+8), C(J+13)=H(I+12),
    // C(J+15)=H(I+4), C(J+16)=H(I+8), C(J+17)=H(I+4)
    // where J = 18*I-18, I=1..4
    // H is 1-indexed: H(1..16). H(I+4) means H at index I+4.
    // H(1)=1,H(2)=x1,H(3)=y1,H(4)=z1, H(5)=1,H(6)=x2,... 
    // So H(I+4) for I=1..4 = H(5),H(6),H(7),H(8) = 1,x2,y2,z2
    // H(I+8) = H(9..12) = 1,x3,y3,z3
    // H(I+12) = H(13..16) = 1,x4,y4,z4

    // Hinv is the inverse. Note: the C matrix uses Hinv (H after INVERD).
    // Wait - H is inverted in place by INVERD. So H now holds Hinv.
    // Let me re-read: CALL INVERD(4,H(1),4,...) - inverts H in place.
    // Then C uses H(I+4) etc which is now Hinv.

    // Hinv 1-indexed column-major: Hinv_f(i) = Hinv((i-1)%4, (i-1)/4)
    auto Hf = [&](int i)->double {
        // i is 1-indexed into the 16-element array (column-major 4x4)
        int idx = i-1;
        int r = idx % 4;
        int c = idx / 4;
        return Hinv(r,c);
    };

    // Build C matrices: C[I] is 6x3
    Matrix<double,6,3> Cmat[4];
    for (int I=1; I<=4; ++I) {
        Cmat[I-1] = Matrix<double,6,3>::Zero();
        // Fortran C(J+k) with J=18*I-18, k=1..17
        // C is 6x3 column-major: C(J+k) -> element (k-1)%6, (k-1)/6
        auto setC = [&](int k, double val){
            int idx = k-1;
            int r = idx % 6;
            int c = idx / 6;
            Cmat[I-1](r,c) = val;
        };
        setC(1,  Hf(I+4));
        setC(5,  Hf(I+8));
        setC(9,  Hf(I+12));
        setC(11, Hf(I+12));
        setC(12, Hf(I+8));
        setC(13, Hf(I+12));
        setC(15, Hf(I+4));
        setC(16, Hf(I+8));
        setC(17, Hf(I+4));
    }

    // HDETER = |HDETER| / 6.0 (IOPT=0 case)
    HDETER = std::fabs(HDETER) / 6.0;

    // Now compute K. For each of 4 points:
    // GCT = C_i^T * G  (3x6) * HDETER
    // K_ij = GCT * C_j  (3x3)
    // Assemble into 12x12

    Matrix<double,12,12> K = Matrix<double,12,12>::Zero();

    // GCT for each i: 3x6
    Matrix<double,3,6> GCT[4];
    for (int i=0;i<4;i++){
        GCT[i] = Cmat[i].transpose() * G * HDETER;
    }

    // K_ij block = GCT_i * C_j  (3x3)
    for (int i=0;i<4;i++){
        for (int j=0;j<4;j++){
            Matrix3d Kij = GCT[i] * Cmat[j];
            K.block<3,3>(3*i,3*j) = Kij;
        }
    }

    // Output JSON
    std::cout << std::setprecision(10);
    std::cout << "{\"stiffness_matrix\":[";
    for (int r=0;r<12;r++){
        std::cout << "[";
        for (int c=0;c<12;c++){
            std::cout << std::scientific << K(r,c);
            if (c<11) std::cout << ",";
        }
        std::cout << "]";
        if (r<11) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}
